SELECT s.city, CASE WHEN s.rating >= 4.2 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(i.quantity), 2) AS stddev_quantity, AVG(i.quantity) AS avg_quantity FROM inventory i LEFT JOIN products p ON p.id = i.product_id LEFT JOIN suppliers s ON p.supplier_id = s.id GROUP BY s.city, CASE WHEN s.rating >= 4.2 THEN 'high' WHEN s.rating >= 2.6 THEN 'mid' ELSE 'low' END;
